#include <memory>
#include <iostream>

class Resource { public: int data = 42; ~Resource() {} };

void transfer_ownership(std::auto_ptr<Resource> p) {
    std::cout << "Inside function, resource transferred.\n";
}

int main() {
    std::auto_ptr<Resource> ap1(new Resource);

    // Ownership transferred to ap2. ap1 becomes null.
    std::auto_ptr<Resource> ap2 = ap1; 

    // std::cout << ap1->data; // DANGER: UB/Crash (ap1 is null)

    // Ownership transferred to function argument.
    transfer_ownership(ap2);

    // std::cout << ap2->data; // DANGER: UB/Crash (ap2 is null)

    return 0; 
}
